import { defineConfig } from 'astro/config';
import starlight from '@astrojs/starlight';
import sitemap from '@astrojs/sitemap';

// Content collections are populated by `docswright sync` into src/content/docs,
// one directory per component/version (e.g. wiki/current/, demo-docs/current/).
// Starlight's default sidebar is fully autogenerated from that tree.
export default defineConfig({
  site: 'http://localhost:4000',
  integrations: [starlight({ title: 'docswright' }), sitemap()],
});
